mod support;
use std::{hint::black_box, time::{Duration, Instant}};
use support::{Endpoint, Scenario, Session};

fn run<'a, M: Endpoint<'a>, const YIELD: bool>(mut session: Session<'a, M, YIELD, false>, seconds: u64) {
    for _ in 0..100 { black_box(session.round_trip()); }
    let begin = Instant::now();
    let mut iterations = 0u64;
    while begin.elapsed() < Duration::from_secs(seconds) {
        for _ in 0..100 {
            black_box(session.round_trip());
        }
        iterations += 100;
    }
    println!("iterations={iterations} elapsed_ns={} ns_per_exchange={:.2}", begin.elapsed().as_nanos(), begin.elapsed().as_nanos() as f64 / iterations as f64);
}

fn main() {
    let args: Vec<_> = std::env::args().collect();
    let scenario = match args[1].as_str() {
        "small" => Scenario::fixed(128),
        "fixed" => Scenario::fixed(1024 * 1024),
        "chunked" => Scenario::chunked(1024 * 1024, support::IO_BYTES),
        _ => panic!("scenario"),
    };
    let seconds = args.get(4).map(|s| s.parse().unwrap()).unwrap_or(5);
    match (args[2].as_str(), args[3].as_str()) {
        ("client", "continue") => {
            support::client::<false, true>(&scenario).round_trip();
            run(support::client::<false, false>(&scenario), seconds);
        }
        ("server", "continue") => {
            support::server::<false, true>(&scenario).round_trip();
            run(support::server::<false, false>(&scenario), seconds);
        }
        ("client", "yield") => {
            support::client::<true, true>(&scenario).round_trip();
            run(support::client::<true, false>(&scenario), seconds);
        }
        ("server", "yield") => {
            support::server::<true, true>(&scenario).round_trip();
            run(support::server::<true, false>(&scenario), seconds);
        }
        _ => panic!("role/mode"),
    }
}

