#[path = "/tmp/http1-transition-study/support-timers.rs"]
mod support;
use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering::Relaxed};
use support::{Endpoint, Scenario, Session};

static ENABLED: AtomicBool = AtomicBool::new(false);
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
static REALLOCS: AtomicUsize = AtomicUsize::new(0);
static DEALLOCS: AtomicUsize = AtomicUsize::new(0);
static EVENTS: AtomicUsize = AtomicUsize::new(0);
static SIZES: [AtomicUsize; 32] = [const { AtomicUsize::new(0) }; 32];
struct Counting;

fn record(counter: &AtomicUsize, bytes: usize) {
    if ENABLED.load(Relaxed) {
        counter.fetch_add(1, Relaxed);
        let i = EVENTS.fetch_add(1, Relaxed);
        if let Some(slot) = SIZES.get(i) {
            slot.store(bytes, Relaxed);
        }
    }
}

// Diagnostic-only allocator; all allocation operations delegate unchanged to System.
unsafe impl GlobalAlloc for Counting {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let ptr = unsafe { System.alloc(layout) };
        if !ptr.is_null() { record(&ALLOCS, layout.size()); }
        ptr
    }
    unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
        let ptr = unsafe { System.alloc_zeroed(layout) };
        if !ptr.is_null() { record(&ALLOCS, layout.size()); }
        ptr
    }
    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        let result = unsafe { System.realloc(ptr, layout, size) };
        if !result.is_null() { record(&REALLOCS, size); }
        result
    }
    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
        if ENABLED.load(Relaxed) { DEALLOCS.fetch_add(1, Relaxed); }
        unsafe { System.dealloc(ptr, layout) };
    }
}
#[global_allocator]
static ALLOCATOR: Counting = Counting;

fn probe<'a, M: Endpoint<'a>>(mut session: Session<'a, M, false, false>) {
    for _ in 0..10 { std::hint::black_box(session.round_trip()); }
    for sample in 0..3 {
        ALLOCS.store(0, Relaxed);
        REALLOCS.store(0, Relaxed);
        DEALLOCS.store(0, Relaxed);
        EVENTS.store(0, Relaxed);
        ENABLED.store(true, Relaxed);
        std::hint::black_box(session.round_trip());
        ENABLED.store(false, Relaxed);
        let sizes: Vec<_> = SIZES.iter().take(EVENTS.load(Relaxed)).map(|s| s.load(Relaxed)).collect();
        println!("sample={sample} alloc={} realloc={} dealloc={} requested_sizes={sizes:?}", ALLOCS.load(Relaxed), REALLOCS.load(Relaxed), DEALLOCS.load(Relaxed));
    }
}
fn main() {
    for (name,scenario) in [
        ("small",Scenario::fixed(128)),
        ("fixed",Scenario::fixed(1024*1024)),
        ("chunked",Scenario::chunked(1024*1024,support::IO_BYTES)),
    ] {
        println!("{name} client");
        probe(support::client::<false,false>(&scenario));
        println!("{name} server");
        probe(support::server::<false,false>(&scenario));
    }
}
